const description: { en: string; ja: string } = {"en":"Three pointed leaves rise behind a broad fruit. A forward leaf partly covers the fruit on the left, and the branch slants down between the two lower leaves.","ja":"幅広い実の後ろに三枚のとがった葉を立てます。左手前の葉が実の一部に重なり、下の二枚の葉の間から枝が斜めに下がります。"};

